"""Tests for commit_policy.py. Run: python3 -m unittest discover -s .github/scripts -p 'test_*.py'"""
import unittest
import urllib.error

import commit_policy as cp

# Built from parts so this file's own commit message and diff stay plain text.
ROBOT = "\U0001F916"
VENDOR = "anthropic.com"

FLAGGED = {
    "co-author trailer": f"Fix parser\n\nCo-Authored-By: Claude Opus <noreply@{VENDOR}>",
    "co-author trailer lower case": "Fix\n\nco-authored-by: GitHub Copilot <copilot@github.com>",
    "co-author ChatGPT": "Fix\n\nCo-authored-by: ChatGPT <bot@example.com>",
    "co-author plain AI": "Fix\n\nCo-authored-by: AI <ai@example.com>",
    "co-author cursor agent": "Fix\n\nCo-authored-by: Cursor Agent <cursoragent@cursor.com>",
    "signed-off-by gemini": "Fix\n\nSigned-off-by: Gemini <g@example.com>",
    "assisted-by trailer": "Fix\n\nAssisted-by: GPT-5 via codex",
    "ai-assisted trailer": "Fix\n\nAI-Assisted: yes",
    "generated with link": f"Fix\n\n{ROBOT} Generated with [Claude Code](https://claude.com/claude-code)",
    "generated with, no emoji": "Fix\n\nGenerated with [Claude Code]",
    "generated by an AI": "Add tests\n\nThese were generated by an AI.",
    "written using an LLM": "Docs\n\nWritten using an LLM",
    "robot emoji alone": f"{ROBOT} tidy",
    "vendor address": f"Fix\n\nThanks noreply@{VENDOR}",
}

CLEAN = {
    "plain": "Scaffold backend: Spring Boot 4.1.2, Java 25 (T0.1)",
    "human co-author": "Fix\n\nCo-authored-by: Kai Moradi <kai@example.com>",
    "words containing ai": "Maintain the email domain list; explain the main chain",
    "generated by a tool": "Regenerate tokens generated by build.mjs",
    "generated by spring aot": "Hints for classes generated by the Spring AOT engine",
    "cursor in ui text": "Tooltip created by cursor hover follows the pointer",
    "claude dir": "Ignore .claude/ in git",
    "mentions agents": "Install role agents from asancart/documents",
    "empty": "",
}


def commit(sha="a" * 40, verified=True, reason="valid", message="Fix"):
    return {"sha": sha, "commit": {"message": message, "verification": {"verified": verified, "reason": reason}}}


class MarkerTest(unittest.TestCase):
    def test_flags_ai_attribution(self):
        for name, msg in FLAGGED.items():
            with self.subTest(name):
                self.assertTrue(cp.ai_markers(msg), f"not flagged: {msg!r}")

    def test_leaves_clean_messages(self):
        for name, msg in CLEAN.items():
            with self.subTest(name):
                self.assertEqual(cp.ai_markers(msg), [], f"wrongly flagged: {msg!r}")

    def test_none_is_clean(self):
        self.assertEqual(cp.ai_markers(None), [])


class CommitTest(unittest.TestCase):
    def test_signed_clean_commit_passes(self):
        self.assertEqual(cp.check_commit(commit()), [])

    def test_unsigned_commit_fails(self):
        problems = cp.check_commit(commit(verified=False, reason="unsigned"))
        self.assertEqual(len(problems), 1)
        self.assertIn("unsigned", problems[0])

    def test_bad_signature_fails(self):
        self.assertIn("unknown_key", cp.check_commit(commit(verified=False, reason="unknown_key"))[0])

    def test_missing_verification_fails(self):
        self.assertTrue(cp.check_commit({"sha": "b" * 40, "commit": {"message": "x"}}))

    def test_trailer_fails_even_when_signed(self):
        problems = cp.check_commit(commit(message=FLAGGED["co-author trailer"]))
        self.assertTrue(any("AI attribution" in p for p in problems))


class FakeApi:
    def __init__(self, responses):
        self.responses, self.calls = responses, []

    def get(self, path):
        self.calls.append(path)
        value = self.responses.get(path.split("?")[0])
        if isinstance(value, Exception):
            raise value
        if callable(value):
            return value(path)
        if value is None:
            raise AssertionError(f"unexpected call {path}")
        return value


def not_found():
    return urllib.error.HTTPError("u", 404, "Not Found", {}, None)


class CollectTest(unittest.TestCase):
    repo = {"default_branch": "main"}

    def test_push_uses_before_after(self):
        api = FakeApi({f"compare/{'1' * 40}...{'2' * 40}": {"total_commits": 1, "commits": [commit()]}})
        event = {"before": "1" * 40, "after": "2" * 40, "ref": "refs/heads/x", "repository": self.repo}
        commits, texts, _ = cp.collect(api, "push", event, "2" * 40)
        self.assertEqual(len(commits), 1)
        self.assertEqual(texts, [])

    def test_new_branch_compares_with_default(self):
        api = FakeApi({f"compare/main...{'2' * 40}": {"total_commits": 2, "commits": [commit(), commit()]}})
        event = {"before": cp.ZERO_SHA, "after": "2" * 40, "ref": "refs/heads/x", "repository": self.repo}
        commits, _, what = cp.collect(api, "push", event, "2" * 40)
        self.assertEqual(len(commits), 2)
        self.assertIn("main...", what)

    def test_lost_before_falls_back_to_default(self):
        api = FakeApi({
            f"compare/{'1' * 40}...{'2' * 40}": not_found(),
            f"compare/main...{'2' * 40}": {"total_commits": 1, "commits": [commit()]},
        })
        event = {"before": "1" * 40, "after": "2" * 40, "ref": "refs/heads/x", "repository": self.repo}
        self.assertEqual(len(cp.collect(api, "push", event, "2" * 40)[0]), 1)

    def test_deleted_branch_checks_nothing(self):
        event = {"deleted": True, "before": "1" * 40, "after": cp.ZERO_SHA, "repository": self.repo}
        self.assertEqual(cp.collect(FakeApi({}), "push", event, "")[0], [])

    def test_compare_reads_every_page(self):
        pages = {1: [commit()] * 100, 2: [commit()] * 30}
        api = FakeApi({"compare/main...h": lambda p: {"total_commits": 130,
                                                       "commits": pages[int(p.rsplit("page=", 1)[1])]}})
        self.assertEqual(len(cp.compare(api, "main", "h")), 130)

    def test_pull_request_checks_commits_title_and_body(self):
        api = FakeApi({"pulls/7/commits": [commit()]})
        event = {"pull_request": {"number": 7, "title": "CI", "body": FLAGGED["generated with link"]},
                 "repository": self.repo}
        commits, texts, _ = cp.collect(api, "pull_request", event, "")
        self.assertEqual(len(commits), 1)
        self.assertEqual([label for label, _ in texts], ["PR title", "PR body"])
        self.assertTrue(cp.ai_markers(texts[1][1]))


if __name__ == "__main__":
    unittest.main()
